{
  "happy_paths": [
    {
      "id": "TC-001",
      "title": "Samsung kapıda takas sürecinde garanti state değişikliğinin başarılı tamamlanması (async ChangeStateAsync)",
      "steps": [
        "Partner portalda Samsung kapıda takas sürecine ait mevcut bir takas talebini bul, talep detay sayfasına git",
        "Talep detayında garanti sürecine ait state bilgisinin mevcut state'ini not al (örneğin 'Beklemede' gibi listelenen değer)",
        "Talep detayında garanti state değişikliği aksiyonunu tetikle (örneğin uygun 'Devam Et' veya 'Onayla' aksiyonunu kullanarak süreci bir sonraki adıma geçir)",
        "Aksiyon sonrası ekrandaki loading veya işlem devam ediyor göstergesinin kaybolmasını bekle",
        "Garanti state bilgisinin yeni state'e güncellendiğini ve önceki state ile farklı olduğunu doğrula"
      ],
      "expected": "Garanti state değişikliği aksiyonu tetiklendiğinde backend'deki async ChangeStateAsync çağrısı hatasız tamamlanmalı ve UI üzerinde talebin garanti state'i güncel değeriyle görüntülenmeli"
    },
    {
      "id": "TC-002",
      "title": "Samsung kapıda takas sürecinde garanti state değişikliğinin idempotent çalışması",
      "steps": [
        "Partner portalda Samsung kapıda takas sürecine ait bir takas talebinin detay sayfasına git",
        "Talep için garanti state değişikliği aksiyonunu bir kez tetikle ve yeni state'in ekranda güncellendiğini doğrula",
        "Aynı state değişikliğini yeniden tetikleyebileceğin aynı aksiyonu tekrar çalıştır (mümkünse aynı hedef state'e veya bir sonraki mantıklı hedef state'e ilerlet)",
        "İkinci aksiyon sonrası ekranda hata mesajı oluşmadığını ve talep detayının yüklenmeye devam ettiğini doğrula",
        "Talebin garanti state geçmişi veya güncel state alanında çakışan ya da tutarsız bir state bilgisi görünmediğini doğrula"
      ],
      "expected": "ChangeStateAsync çağrıları ardışık tetiklense bile Samsung kapıda takas talebinin garanti state bilgisinde çifte işleme veya tutarsız state oluşmamalı, UI tarafında hata mesajı çıkmamalı"
    },
    {
      "id": "TC-003",
      "title": "Samsung kapıda takas sürecinde garanti state değişikliğinin trade-in sipariş başarı sayfasına doğru yansıması",
      "steps": [
        "Samsung kapıda takas sürecinde trade-in siparişi oluşturulmuş ve sipariş başarı sayfasına yönlendirilmiş bir kullanıcı için trade-in başarı sayfasına git",
        "Başarı sayfasında sipariş numarası ve Samsung kapıda takas bilgilerini görüntüle, mevcut garanti/takas durum bilgisini not al",
        "Aynı siparişe bağlı Samsung kapıda takas talebinin partner portal detay ekranından garanti state değişikliği aksiyonunu tetikle",
        "Kısa bir süre sonra web arayüzünde başarı sayfasını yenile veya ilgili trade-in detay sayfasını tekrar aç",
        "Başarı sayfasında veya trade-in detayında gösterilen Samsung kapıda takas/garanti durum bilgisinin backend'deki yeni state ile uyumlu olacak şekilde güncellendiğini doğrula"
      ],
      "expected": "GarantiStrategy.ChangeStateAsync ile yapılan state değişimi, Samsung kapıda takas sürecine bağlı trade-in sipariş başarı sayfasında gösterilen durum bilgisine tutarlı ve gecikmesiz biçimde yansıtılmalı"
    },
    {
      "id": "TC-004",
      "title": "Samsung kapıda takas sürecinde garanti state değişikliğinin warranty tamamlama akışına etkisi",
      "steps": [
        "Backoffice'e giriş yapılmış durumda warranty modülünde Samsung kapıda takas sürecinden gelen bir garanti kaydını bul ve ilgili talep detayını aç",
        "Talep detayında mevcut warranty state'ini ve Samsung kapıda takasla ilişkili olduğunu gösteren bilgileri not al",
        "Partner portal veya ilgili backoffice aksiyonları üzerinden bu garanti kaydı için state değişikliği aksiyonunu tetikle (ChangeStateAsync tetiklenecek aksiyon)",
        "Backoffice warranty listesinde veya detay ekranında garanti kaydını yenileyerek güncel state bilgisini kontrol et",
        "Garanti kaydının yeni state'inin JIRA sürecinde tanımlanan Samsung kapıda takas akışına uygun olarak doğru listeye (örneğin işlemdekiler veya tamamlananlar) taşındığını doğrula"
      ],
      "expected": "Samsung kapıda takas kaynaklı garanti kaydı için tetiklenen ChangeStateAsync çağrısı sonrası warranty modülündeki state geçişleri doğru çalışmalı ve ilgili kayıt doğru state altında listelenmeli"
    }
  ],
  "edge_cases": [
    {
      "id": "EC-001",
      "title": "Samsung kapıda takas sürecinde ardışık hızlı garanti state değişikliği istekleri (async yarış durumu)",
      "steps": [
        "Partner portalda Samsung kapıda takas sürecine ait bir takas talebinin detay sayfasına git",
        "Garanti state değişikliği aksiyonunun bulunduğu alanda, mümkün olan en kısa sürede arka arkaya iki kez state değiştirecek aksiyonu tetikle (örneğin hızla iki kez 'Devam Et' veya benzeri state ilerletme aksiyonuna bas)",
        "Ekranda oluşabilecek hata veya uyarı mesajlarını gözle, sayfanın kilitlenmediğini ve talep detayının yüklenmeye devam ettiğini doğrula",
        "Talebin güncel garanti state alanını ve varsa state geçmişi bölümünü kontrol ederek son görünen state'in iş kurallarına göre geçerli ve tekil bir state olduğunu doğrula"
      ],
      "expected": "ChangeStateAsync async olarak arka arkaya tetiklense bile Samsung kapıda takas talebinin garanti state bilgisinde yarış koşulu kaynaklı atlama, geri dönüş veya tutarsızlık oluşmamalı, UI tarafında talep detay sayfası sağlıklı şekilde görüntülenmeye devam etmeli"
    }
  ],
  "skip_reason": [
    {
      "area": "Backend GarantiStrategy.ChangeStateAsync iç işleyişi ve partner entegrasyonları",
      "reason": "Değişiklik yalnızca backend servis imzasını async hale getiriyor, partner entegrasyonlarının zamanlama ve retry mekanizmaları direkt UI üzerinden gözlemlenemediği için düşük seviye concurrency veya thread yönetimi problemleri sadece UI tabanlı E2E testleriyle güvenilir biçimde doğrulanamaz"
    }
  ]
}
